import heapq

EDGES = {
    "Alice": {"Bob": 0.6, "Eve": 0.9},
    "Bob": {"Peter": 0.8},
    "Peter": {"Carol": 0.4},
    "Eve": {"Carol": 0.1},
    "Carol": {},
}

def all_paths(g, src, dst, path=None):
    path = (path or []) + [src]
    if src == dst:
        yield path
        return
    for nxt in g[src]:
        if nxt not in path:
            yield from all_paths(g, nxt, dst, path)

def path_trust(g, path):
    t = 1.0
    for a, b in zip(path, path[1:]):
        t *= g[a][b]
    return t

def best_trust(g, src):
    # Dijkstra "massimizzante": il prodotto di pesi in (0,1] non cresce mai lungo un cammino
    best = {src: 1.0}
    heap = [(-1.0, src)]
    while heap:
        neg, u = heapq.heappop(heap)
        t = -neg
        if t < best.get(u, 0):
            continue
        for v, w in g[u].items():
            if t * w > best.get(v, 0):
                best[v] = t * w
                heapq.heappush(heap, (-best[v], v))
    return best

for p in all_paths(EDGES, "Alice", "Carol"):
    print(" -> ".join(p), round(path_trust(EDGES, p), 3))
print({k: round(v, 3) for k, v in sorted(best_trust(EDGES, "Alice").items())})

