import base64, hashlib
import json

JWT = ("eyJhbGciOiJFUzI1NksiLCJ0eXAiOiJKV1QifQ."
       "."
       "wLtVPIIMeRZE0z9er0ybzhl3N1niZe0HgM1nPqaSVwsAi2kQCxDtrY0GkQkQSaY6UhzjqH-WouxmY8smjZdyWA")

def b64url_decode(s):
    return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))


P = 2**256 - 2**32 - 977
N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141
G = (0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798,
     0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8)

def add(A, B):
    if A is None: return B
    if B is None: return A
    if A[0] == B[0] and (A[1] + B[1]) % P == 0: return None
    if A == B: l = 3 * A[0] * A[0] * pow(2 * A[1], -1, P) % P
    else:      l = (B[1] - A[1]) * pow(B[0] - A[0], -1, P) % P
    x = (l * l - A[0] - B[0]) % P
    return (x, (l * (A[0] - x) - A[1]) % P)

def mul(k, A):
    R = None
    while k:
        if k & 1: R = add(R, A)
        A = add(A, A); k >>= 1
    return R

def lift_x(x, odd):
    y = pow((x**3 + 7) % P, (P + 1) // 4, P)
    return (x, y if y % 2 == odd else P - y)

def decompress(hexkey):
    b = bytes.fromhex(hexkey)
    return lift_x(int.from_bytes(b[1:], "big"), b[0] == 3)

def compress(Q):
    return ("03" if Q[1] % 2 else "02") + format(Q[0], "064x")

def verify(z, r, s, Q):
    w = pow(s, -1, N)
    X = add(mul(z * w % N, G), mul(r * w % N, Q))
    return X is not None and X[0] % N == r

def recover(z, r, s, v):
    R = lift_x(r, v)                      # (r < P - N, quindi x = r)
    rinv = pow(r, -1, N)
    return add(mul(s * rinv % N, R), mul((-z * rinv) % N, G))

